<?php
require_once __DIR__.'/includes/functions.php';$q=trim($_GET['q']??'');$rows=[];$page=$pages=1;if($q!==''){$like="%{$q}%";$c=db()->prepare("SELECT COUNT(*) FROM news WHERE status='published' AND deleted_at IS NULL AND (title LIKE ? OR summary LIKE ? OR details LIKE ?)");$c->execute([$like,$like,$like]);[$page,$pages,$offset]=paginate((int)$c->fetchColumn(),9);$s=db()->prepare("SELECT n.*,c.name category FROM news n LEFT JOIN categories c ON c.id=n.category_id WHERE n.status='published' AND n.deleted_at IS NULL AND (n.title LIKE ? OR n.summary LIKE ? OR n.details LIKE ?) ORDER BY n.published_at DESC LIMIT 9 OFFSET {$offset}");$s->execute([$like,$like,$like]);$rows=$s->fetchAll();}$pageTitle='البحث';require __DIR__.'/includes/header.php';?><div class="container py-5"><h1 class="section-title">البحث في الأخبار</h1><form class="panel p-3 mb-5"><div class="input-group input-group-lg"><input class="form-control" name="q" required placeholder="اكتب كلمات البحث" value="<?=e($q)?>"><button class="btn btn-primary"><i class="bi bi-search"></i> بحث</button></div></form><?php if($q!==''):?><p class="text-secondary">نتائج البحث عن: <strong><?=e($q)?></strong></p><div class="row g-4"><?php foreach($rows as $a):?><div class="col-md-6 col-lg-4"><article class="news-card"><img src="<?=imageUrl($a['image'])?>"><div class="p-3"><small class="text-danger"><?=e($a['category'])?></small><h2 class="h5 fw-bold mt-2"><a class="text-dark text-decoration-none" href="<?=url('news.php?slug='.rawurlencode($a['slug']))?>"><?=e($a['title'])?></a></h2><p class="small text-secondary"><?=e(excerpt($a['summary']))?></p></div></article></div><?php endforeach;if(!$rows):?><div class="col-12 panel p-5 text-center">لم نجد نتائج مطابقة. جرّب كلمات أخرى.</div><?php endif;?></div><div class="mt-5"><?=paginationLinks($page,$pages)?></div><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>
